package com.opensocket.aievent.core.issuetracking.core;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
import com.opensocket.aievent.core.integration.identity.IntegrationRiskLevel;import com.opensocket.aievent.core.issuetracking.change.*;
class ExternalChangePolicyEngineTest {
 @Test void moreSpecificPolicyWinsBeforePriority(){OffsetDateTime now=OffsetDateTime.parse("2026-07-27T00:00:00Z");var broad=policy("b","",100,ExternalChangeDecisionAction.CREATE_CANDIDATE,now);var scoped=policy("s","connection-1",1,ExternalChangeDecisionAction.REJECT,now);var context=new ExternalChangeEvaluationContext("tenant","connection-1","","","ISSUE-1","",ExternalChangeResourceType.STATUS,"/status",ExternalChangeDirection.PROVIDER_TO_OPENDISPATCH,"closed","","h");assertEquals(ExternalChangeDecisionAction.REJECT,new ExternalChangePolicyEngine().evaluate(context,List.of(broad,scoped),now).action());}
 @Test void authorityFieldsDefaultToCandidate(){OffsetDateTime now=OffsetDateTime.parse("2026-07-27T00:00:00Z");var context=new ExternalChangeEvaluationContext("tenant","connection-1","","","ISSUE-1","",ExternalChangeResourceType.APPROVAL,"/approval",ExternalChangeDirection.PROVIDER_TO_OPENDISPATCH,"approved","","h");var decision=new ExternalChangePolicyEngine().evaluate(context,List.of(),now);assertEquals(ExternalChangeDecisionAction.CREATE_CANDIDATE,decision.action());assertTrue(decision.requiresReauthentication());assertTrue(decision.requiresApproval());}
 private ExternalChangePolicy policy(String id,String connection,int priority,ExternalChangeDecisionAction action,OffsetDateTime now){return new ExternalChangePolicy("tenant",id,id,connection,"","","",ExternalChangeResourceType.STATUS,"/status",ExternalChangeDirection.PROVIDER_TO_OPENDISPATCH,action,IntegrationRiskLevel.HIGH,true,true,false,priority,ExternalChangePolicyStatus.ACTIVE,1,null,null,now);}
}
